import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

const lines = (count, price) => Array.from({ length: count }, () => ({ price, qty: 1 }));

// issue #12: the customer's discount is applied exactly once.
test('total applies the customer discount once (under 10 lines)', () => {
  // 1,000 with a 10% customer discount -> 900
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('total applies the customer discount, then the 5% bulk discount once (10 lines)', () => {
  // subtotal 10,000 -> 9,000 after 10% -> 8,550 after 5% bulk
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('total applies no bulk discount at 9 lines', () => {
  // subtotal 9,000 -> 8,100 after 10%, no bulk discount below 10 lines
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

test('total with discount rate 0 is unchanged by the issue #12 fix', () => {
  // Values recorded from the implementation before the fix (acceptance criterion 3).
  assert.equal(total(lines(10, 1000), 0), 9500);
  assert.equal(total(lines(9, 1000), 0), 9000);
  assert.equal(total(lines(10, 999)), 9491);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
